const CONTROL_ID = 'coordinate-inspector';
const PANEL = 'font:12px/1.5 ui-monospace,SFMono-Regular,Menlo,monospace;background:#fff;color:#111;' +
    'border:1px solid #d4d4d8;border-radius:6px;padding:8px;box-shadow:0 2px 8px rgba(0,0,0,.15);' +
    'min-width:210px;font-variant-numeric:tabular-nums';
/** Slippy-map tile the coordinate falls in, at the current zoom. */
function tileForLatLng(position, zoom) {
    const n = Math.pow(2, zoom);
    const latRad = (position.lat * Math.PI) / 180;
    const x = Math.floor(((position.lng + 180) / 360) * n);
    const y = Math.floor(((1 - Math.log(Math.tan(latRad) + 1 / Math.cos(latRad)) / Math.PI) / 2) * n);
    return { x: x, y: y };
}
/** Degrees to degrees/minutes/seconds, e.g. 48°08'13.2"N */
function toDms(value, positive, negative) {
    const hemisphere = value >= 0 ? positive : negative;
    const abs = Math.abs(value);
    const degrees = Math.floor(abs);
    const minutesFull = (abs - degrees) * 60;
    const minutes = Math.floor(minutesFull);
    const seconds = ((minutesFull - minutes) * 60).toFixed(1);
    return degrees + '°' + minutes + "'" + seconds + '"' + hemisphere;
}
plugin.mapHook.onHook(function () {
    const decimals = Math.min(8, Math.max(2, Number(plugin.settings.get('decimals')) || 5));
    plugin.mapHook.createControl({
        id: CONTROL_ID,
        position: String(plugin.settings.get('position') || 'bottom-right'),
        html: '<div style="' + PANEL + '">' +
            '<div data-coord-latlng>Move the pointer over the map</div>' +
            '<div data-coord-dms style="color:#71717a"></div>' +
            '<div data-coord-tile style="color:#71717a"></div>' +
            '<div data-coord-hint style="margin-top:4px;color:#71717a">Right-click the map to copy</div>' +
            '</div>',
    });
    const root = document.querySelector('[data-map-control-id="' + CONTROL_ID + '"]');
    if (!root) {
        plugin.error('Coordinate inspector: control markup not found in the page');
        return;
    }
    const latLngOut = root.querySelector('[data-coord-latlng]');
    const dmsOut = root.querySelector('[data-coord-dms]');
    const tileOut = root.querySelector('[data-coord-tile]');
    const hintOut = root.querySelector('[data-coord-hint]');
    function show(position) {
        if (latLngOut) {
            latLngOut.textContent = position.lat.toFixed(decimals) + ', ' + position.lng.toFixed(decimals);
        }
        if (dmsOut) {
            dmsOut.textContent = toDms(position.lat, 'N', 'S') + ' ' + toDms(position.lng, 'E', 'W');
        }
        if (tileOut) {
            const zoom = plugin.mapHook.getZoom();
            if (typeof zoom === 'number') {
                const tile = tileForLatLng(position, Math.round(zoom));
                tileOut.textContent = 'tile ' + Math.round(zoom) + '/' + tile.x + '/' + tile.y;
            }
            else {
                tileOut.textContent = '';
            }
        }
    }
    plugin.mapHook.onMouseMove(show);
    plugin.mapHook.onRightClick(function (position) {
        show(position);
        const text = position.lat.toFixed(decimals) + ', ' + position.lng.toFixed(decimals);
        if (!navigator.clipboard) {
            if (hintOut)
                hintOut.textContent = text;
            return;
        }
        navigator.clipboard
            .writeText(text)
            .then(function () {
            if (hintOut)
                hintOut.textContent = 'Copied ' + text;
        })
            .catch(function () {
            // Some sites block clipboard writes; showing the value still lets the user copy it.
            if (hintOut)
                hintOut.textContent = text;
        });
    });
    plugin.log('Coordinate inspector ready');
});

const STYLE_ID = 'map-ext-dark-map';

plugin.mapHook.onHook(function () {
  let brightness = Number(plugin.settings.get('brightness'));
  if (isNaN(brightness) || brightness < 0.3 || brightness > 1.5) brightness = 0.9;

  let contrast = Number(plugin.settings.get('contrast'));
  if (isNaN(contrast) || contrast < 0.5 || contrast > 2) contrast = 1.05;

  // invert + hue-rotate keeps landmasses dark while leaving hues roughly recognisable.
  const filter = 'invert(1) hue-rotate(180deg) brightness(' + brightness + ') contrast(' + contrast + ')';

  const css =
    // Leaflet exposes a real, stable class for just the tile layer, so only that gets
    // filtered — markers, popups and Leaflet's own controls keep their normal colours.
    '.leaflet-tile-pane{filter:' + filter + '}' +
    // Google Maps has no equivalent public hook. Tiles, markers and controls are all
    // rendered inside .gm-style with an internal structure Google does not document and
    // changes between versions — an earlier attempt at guessing a narrower selector
    // (.gm-style > div:first-child > div:first-child) turned out not to match reality.
    // Filtering the whole container is the only option that reliably works, which means
    // markers and Google's own UI controls get inverted too on this engine.
    '.gm-style{filter:' + filter + '}';

  const existing = document.getElementById(STYLE_ID);
  if (existing) existing.remove();

  const style = document.createElement('style');
  style.id = STYLE_ID;
  style.textContent = css;
  document.head.appendChild(style);

  // Injected DOM is not tracked as a layer, so it has to be cleaned up explicitly.
  plugin.onDispose(function () {
    style.remove();
  });

  plugin.log('Dark map applied — brightness', brightness, 'contrast', contrast);
});

const CONTROL_ID = 'open-elsewhere';
const PANEL = 'font:12px/1.45 system-ui,sans-serif;background:#fff;color:#111;border:1px solid #d4d4d8;' +
    'border-radius:6px;padding:8px;box-shadow:0 2px 8px rgba(0,0,0,.15)';
const LINK = 'display:block;padding:4px 6px;color:#1d4ed8;text-decoration:none;border-radius:4px;white-space:nowrap';
// Formats confirmed against each site's own permalink builder.
const TARGETS = [
    {
        key: 'osm',
        label: 'OpenStreetMap',
        url: (lat, lng, z) => 'https://www.openstreetmap.org/#map=' + z + '/' + lat.toFixed(5) + '/' + lng.toFixed(5),
    },
    {
        key: 'google',
        label: 'Google Maps',
        url: (lat, lng, z) => 'https://www.google.com/maps/@' + lat.toFixed(6) + ',' + lng.toFixed(6) + ',' + z + 'z',
    },
    {
        key: 'bing',
        label: 'Bing Maps',
        url: (lat, lng, z) => 'https://www.bing.com/maps?cp=' + lat.toFixed(6) + '~' + lng.toFixed(6) + '&lvl=' + z,
    },
    {
        key: 'openrailwaymap',
        label: 'OpenRailwayMap',
        url: (lat, lng, z) => 'https://www.openrailwaymap.org/?style=standard&lat=' + lat.toFixed(6) + '&lon=' + lng.toFixed(6) + '&zoom=' + z,
    },
    {
        key: 'opentopomap',
        label: 'OpenTopoMap',
        url: (lat, lng, z) => 'https://opentopomap.org/#map=' + z + '/' + lat.toFixed(5) + '/' + lng.toFixed(5),
    },
    {
        key: 'mapillary',
        label: 'Mapillary',
        url: (lat, lng, z) => 'https://www.mapillary.com/app/?lat=' + lat.toFixed(6) + '&lng=' + lng.toFixed(6) + '&z=' + z,
    },
    {
        key: 'geohack',
        label: 'GeoHack (all services)',
        url: (lat, lng) => 'https://geohack.toolforge.org/geohack.php?params=' + lat.toFixed(6) + '_N_' + lng.toFixed(6) + '_E',
    },
];
plugin.mapHook.onHook(function () {
    const enabledRaw = String(plugin.settings.get('services') || 'osm,google,openrailwaymap,geohack');
    const enabled = enabledRaw.split(',').map(function (part) { return part.trim(); });
    const targets = TARGETS.filter(function (t) { return enabled.indexOf(t.key) !== -1; });
    const shown = targets.length > 0 ? targets : TARGETS;
    let markup = '<div style="' + PANEL + '">' +
        '<div style="font-weight:600;margin-bottom:4px">Open this view in…</div>';
    for (let i = 0; i < shown.length; i++) {
        markup += '<a href="#" data-open-target="' + shown[i].key + '" style="' + LINK + '">' + shown[i].label + '</a>';
    }
    markup += '<div data-open-coords style="margin-top:6px;color:#71717a;font-variant-numeric:tabular-nums"></div></div>';
    plugin.mapHook.createControl({
        id: CONTROL_ID,
        position: String(plugin.settings.get('position') || 'top-left'),
        html: markup,
    });
    const root = document.querySelector('[data-map-control-id="' + CONTROL_ID + '"]');
    if (!root) {
        plugin.error('Open elsewhere: control markup not found in the page');
        return;
    }
    const coords = root.querySelector('[data-open-coords]');
    function currentView() {
        const center = plugin.mapHook.getCenter();
        if (!center)
            return null;
        const zoom = plugin.mapHook.getZoom();
        return { lat: center.lat, lng: center.lng, zoom: typeof zoom === 'number' ? Math.round(zoom) : 14 };
    }
    function refreshCoords() {
        if (!coords)
            return;
        const view = currentView();
        coords.textContent = view ? view.lat.toFixed(5) + ', ' + view.lng.toFixed(5) + ' · z' + view.zoom : '';
    }
    for (let i = 0; i < shown.length; i++) {
        const target = shown[i];
        const link = root.querySelector('[data-open-target="' + target.key + '"]');
        if (!link)
            continue;
        link.addEventListener('click', function (event) {
            event.preventDefault();
            const view = currentView();
            if (!view) {
                plugin.warn('Open elsewhere: the map has no centre yet');
                return;
            }
            // Opened from a real click, so this is a user gesture and not treated as a popup.
            window.open(target.url(view.lat, view.lng, view.zoom), '_blank', 'noopener,noreferrer');
        });
    }
    refreshCoords();
    plugin.mapHook.onMoveEnd(refreshCoords);
    plugin.mapHook.onZoomEnd(refreshCoords);
    plugin.log('Open-elsewhere control ready with', shown.length, 'targets');
});

plugin.mapHook.onHook(function () {
    let opacity = Number(plugin.settings.get('opacity'));
    if (isNaN(opacity) || opacity < 0 || opacity > 1)
        opacity = 1;
    // Seamark tiles are symbol-only and transparent, so they are mostly empty inland — that is
    // expected, not a failure. No Referer header is required by this server.
    plugin.mapHook.createTileLayer({
        urlTemplate: 'https://tiles.openseamap.org/seamark/{z}/{x}/{y}.png',
        attribution: '© OpenSeaMap contributors (CC-BY-SA)',
        opacity: opacity,
        tileSize: 256,
        minZoom: 0,
        maxZoom: 18,
    });
    plugin.log('OpenSeaMap seamark overlay attached — opacity:', opacity);
});

/**
 * One plugin covering many POI types, rather than one plugin per type. Overpass is a donated
 * public service and this extension already ships three plugins that query it, so every extra
 * always-on layer is extra load on it.
 */
const CATEGORIES = [
    { key: 'charging', label: 'EV charging', filter: '"amenity"="charging_station"', color: '#16a34a' },
    { key: 'drinking_water', label: 'Drinking water', filter: '"amenity"="drinking_water"', color: '#0284c7' },
    { key: 'toilets', label: 'Toilets', filter: '"amenity"="toilets"', color: '#7c3aed' },
    { key: 'bicycle_parking', label: 'Bicycle parking', filter: '"amenity"="bicycle_parking"', color: '#2563eb' },
    { key: 'pharmacy', label: 'Pharmacy', filter: '"amenity"="pharmacy"', color: '#dc2626' },
    { key: 'cafe', label: 'Cafe', filter: '"amenity"="cafe"', color: '#b45309' },
    { key: 'supermarket', label: 'Supermarket', filter: '"shop"="supermarket"', color: '#ca8a04' },
    { key: 'viewpoint', label: 'Viewpoint', filter: '"tourism"="viewpoint"', color: '#0d9488' },
];
let sequence = 0;
let debounceTimer;
plugin.mapHook.onHook(function () {
    const categoryKey = String(plugin.settings.get('category') || 'charging');
    let category = CATEGORIES[0];
    for (let i = 0; i < CATEGORIES.length; i++) {
        if (CATEGORIES[i].key === categoryKey)
            category = CATEGORIES[i];
    }
    const color = String(plugin.settings.get('color') || '') || category.color;
    let minZoom = Number(plugin.settings.get('minZoom'));
    if (isNaN(minZoom) || minZoom < 8 || minZoom > 20)
        minZoom = 14;
    const layer = plugin.mapHook.createMarkerLayer();
    function load(bounds) {
        if (!bounds) {
            layer.clear();
            return;
        }
        // Below this zoom the bounding box covers a whole region and the query gets expensive
        // for Overpass while returning more markers than anyone can read.
        const zoom = plugin.mapHook.getZoom();
        if (typeof zoom === 'number' && zoom < minZoom) {
            layer.clear();
            plugin.log('Zoom in to ' + minZoom + '+ to load ' + category.label.toLowerCase());
            return;
        }
        const requestSequence = ++sequence;
        const bbox = [bounds.south, bounds.west, bounds.north, bounds.east].join(',');
        const query = '[out:json][timeout:25];(' +
            'node[' + category.filter + '](' + bbox + ');' +
            'way[' + category.filter + '](' + bbox + ');' +
            ');out center;';
        plugin
            .fetch('https://overpass-api.de/api/interpreter', { method: 'POST', body: query })
            .then(function (response) {
            if (!response.ok)
                throw new Error('Overpass returned HTTP ' + response.status);
            return response.json();
        })
            .then(function (data) {
            if (requestSequence !== sequence)
                return;
            layer.clear();
            const elements = data.elements || [];
            let drawn = 0;
            for (let i = 0; i < elements.length; i++) {
                const element = elements[i];
                const lat = typeof element.lat === 'number' ? element.lat : element.center && element.center.lat;
                const lon = typeof element.lon === 'number' ? element.lon : element.center && element.center.lon;
                if (typeof lat !== 'number' || typeof lon !== 'number')
                    continue;
                const tags = element.tags || {};
                const name = tags.name || category.label;
                layer.addMarker({
                    id: category.key + '-' + element.type + '-' + i,
                    lat: lat,
                    lng: lon,
                    color: color,
                    popup: name,
                    tooltip: name,
                });
                drawn++;
            }
            plugin.log('Loaded ' + drawn + ' ' + category.label.toLowerCase() + ' markers');
        })
            .catch(function (err) {
            if (requestSequence !== sequence)
                return;
            plugin.error(category.label + ' error:', err instanceof Error ? err.message : String(err));
        });
    }
    function schedule(bounds) {
        clearTimeout(debounceTimer);
        debounceTimer = setTimeout(function () {
            load(bounds);
        }, 600);
    }
    schedule(plugin.mapHook.getBounds());
    plugin.mapHook.onMoveEnd(schedule);
    plugin.onDispose(function () {
        clearTimeout(debounceTimer);
        sequence++;
    });
});

let seq = 0;
let debounce;
plugin.mapHook.onHook(function () {
    const layer = plugin.mapHook.createPolylineLayer();
    function load(bounds) {
        if (!bounds) {
            layer.clear();
            return;
        }
        const requestSeq = ++seq;
        const bbox = [bounds.south, bounds.west, bounds.north, bounds.east].join(',');
        const query = `[out:json][timeout:25];\n(\n  way["railway"](${bbox});\n);\nout geom;`;
        plugin
            .fetch('https://overpass-api.de/api/interpreter', { method: 'POST', body: query })
            .then(function (res) {
            return res.json();
        })
            .then(function (data) {
            if (requestSeq !== seq)
                return;
            layer.clear();
            const elements = data.elements || [];
            for (let i = 0; i < elements.length; i++) {
                const el = elements[i];
                if (el.type !== 'way' || !Array.isArray(el.geometry))
                    continue;
                const path = [];
                for (let j = 0; j < el.geometry.length; j++) {
                    const pt = el.geometry[j];
                    if (typeof pt.lat === 'number' && typeof pt.lon === 'number') {
                        path.push({ lat: pt.lat, lng: pt.lon });
                    }
                }
                if (path.length > 1)
                    layer.addPolyline({ path, color: 'red', weight: 2 });
            }
            plugin.log('Loaded ' + elements.length + ' railway segments');
        })
            .catch(function (e) {
            const message = e instanceof Error ? e.message : String(e);
            plugin.error('Railways error:', message);
        });
    }
    function schedule(bounds) {
        clearTimeout(debounce);
        debounce = setTimeout(function () {
            load(bounds);
        }, 500);
    }
    schedule(plugin.mapHook.getBounds());
    plugin.mapHook.onMoveEnd(schedule);
});

const CONTROL_ID = 'saved-views';
const STORE_KEY = 'views';
const PANEL = 'font:12px/1.45 system-ui,sans-serif;background:#fff;color:#111;border:1px solid #d4d4d8;' +
    'border-radius:6px;padding:8px;box-shadow:0 2px 8px rgba(0,0,0,.15);min-width:200px';
const BTN = 'font:12px/1 system-ui,sans-serif;padding:5px 9px;border:1px solid #d4d4d8;border-radius:4px;' +
    'background:#f4f4f5;color:#111;cursor:pointer;margin-right:4px';
plugin.mapHook.onHook(function () {
    plugin.mapHook.createControl({
        id: CONTROL_ID,
        position: String(plugin.settings.get('position') || 'bottom-left'),
        html: '<div style="' + PANEL + '">' +
            '<div style="font-weight:600;margin-bottom:6px">Saved views</div>' +
            '<select data-views-list style="width:100%;margin-bottom:6px;font:12px system-ui,sans-serif;padding:4px"></select>' +
            '<div>' +
            '<button type="button" data-views-go style="' + BTN + '">Go</button>' +
            '<button type="button" data-views-save style="' + BTN + '">Save…</button>' +
            '<button type="button" data-views-delete style="' + BTN + '">Delete</button>' +
            '</div>' +
            '<div data-views-status style="margin-top:6px;color:#71717a"></div>' +
            '</div>',
    });
    const root = document.querySelector('[data-map-control-id="' + CONTROL_ID + '"]');
    if (!root) {
        plugin.error('Saved views: control markup not found in the page');
        return;
    }
    const list = root.querySelector('[data-views-list]');
    const status = root.querySelector('[data-views-status]');
    let views = [];
    function setStatus(text) {
        if (status)
            status.textContent = text;
    }
    function renderList() {
        if (!list)
            return;
        list.innerHTML = '';
        if (views.length === 0) {
            const option = document.createElement('option');
            option.textContent = 'No saved views yet';
            option.value = '';
            list.appendChild(option);
            return;
        }
        for (let i = 0; i < views.length; i++) {
            const option = document.createElement('option');
            option.value = String(i);
            option.textContent = views[i].name + '  (z' + views[i].zoom + ')';
            list.appendChild(option);
        }
    }
    function persist() {
        return plugin.store.set(STORE_KEY, views).catch(function (err) {
            plugin.error('Saved views: could not save —', err instanceof Error ? err.message : String(err));
        });
    }
    plugin.store
        .get(STORE_KEY)
        .then(function (stored) {
        if (Array.isArray(stored))
            views = stored;
        renderList();
        setStatus(views.length + ' saved');
    })
        .catch(function (err) {
        plugin.error('Saved views: could not load —', err instanceof Error ? err.message : String(err));
        renderList();
    });
    const goButton = root.querySelector('[data-views-go]');
    const saveButton = root.querySelector('[data-views-save]');
    const deleteButton = root.querySelector('[data-views-delete]');
    if (goButton) {
        goButton.addEventListener('click', function () {
            if (!list || !list.value)
                return;
            const view = views[Number(list.value)];
            if (!view)
                return;
            plugin.mapHook.setView({ lat: view.lat, lng: view.lng }, view.zoom);
            setStatus('Moved to ' + view.name);
        });
    }
    if (saveButton) {
        saveButton.addEventListener('click', function () {
            const center = plugin.mapHook.getCenter();
            if (!center) {
                setStatus('The map has no centre yet');
                return;
            }
            const zoom = plugin.mapHook.getZoom();
            const suggested = 'View ' + (views.length + 1);
            const name = window.prompt('Name this view', suggested);
            if (!name)
                return;
            views.push({
                name: name,
                lat: center.lat,
                lng: center.lng,
                zoom: typeof zoom === 'number' ? Math.round(zoom) : 14,
            });
            renderList();
            setStatus(views.length + ' saved');
            void persist();
        });
    }
    if (deleteButton) {
        deleteButton.addEventListener('click', function () {
            if (!list || !list.value)
                return;
            const index = Number(list.value);
            if (!views[index])
                return;
            const removed = views.splice(index, 1)[0];
            renderList();
            setStatus('Deleted ' + removed.name);
            void persist();
        });
    }
    plugin.log('Saved views ready');
});

// Waymarked Trails serves a transparent route overlay per activity, designed to sit on top of
// an existing basemap. Verified live: all four render and none require a Referer header.
const ROUTES = ['hiking', 'cycling', 'riding', 'slopes'];
plugin.mapHook.onHook(function () {
    let route = String(plugin.settings.get('route') || 'hiking');
    if (ROUTES.indexOf(route) === -1)
        route = 'hiking';
    let opacity = Number(plugin.settings.get('opacity'));
    if (isNaN(opacity) || opacity < 0 || opacity > 1)
        opacity = 1;
    plugin.mapHook.createTileLayer({
        urlTemplate: 'https://tile.waymarkedtrails.org/' + route + '/{z}/{x}/{y}.png',
        attribution: '© waymarkedtrails.org, OpenStreetMap contributors (CC-BY-SA)',
        opacity: opacity,
        tileSize: 256,
        minZoom: 0,
        maxZoom: 18,
    });
    plugin.log('Waymarked Trails overlay attached — route:', route, 'opacity:', opacity);
});
